constexpr auto Max=std::numeric_limits<std::uint64_t>::max();
static_assert(16+768+16+96+44*MaxWorkers==1248&&WireBytes==1280);
constexpr std::uint32_t Magic=0x32564249; // Explicit bytes I B V 2.
template<std::size_t N>std::optional<std::string_view> field(const std::array<char,N>& a)noexcept{auto end=std::find(a.begin(),a.end(),char{});if(end==a.end()||end==a.begin()||!std::all_of(end,a.end(),[](char c){return c==0;}))return {};return std::string_view(a.data(),std::size_t(end-a.begin()));}
