bool reached(ClockPair now,ClockPair deadline)noexcept{return now.generation!=deadline.generation||now.monotonic>=deadline.monotonic||now.boottime>=deadline.boottime;}
bool window(ClockPair issued,ClockPair end,Ns duration)noexcept{ClockPair expected;return plus(issued,duration,expected)&&expected==end;}
bool next(std::uint64_t value,std::uint64_t& result)noexcept{if(value>=Max-1)return false;result=value+1;return true;}
bool peerMatches(VerifiedPeer peer,VerifiedPeer bound,std::uint32_t uid,std::uint32_t pid)noexcept{return peer.verified&&bound.verified&&peer.uid==uid&&bound.uid==uid&&peer.pid==pid&&bound.pid==pid&&peer.connection!=0&&peer.connection==bound.connection;}
Reason authority(Authority a)noexcept{if(!a.reference)return Reason::ReferenceLost;if(!a.identity)return Reason::IdentityLost;if(!a.manager)return Reason::ManagerLost;if(!a.power)return Reason::PowerLost;return Reason::None;}
