bool proofWithinBudget(const ClosureProof& p,const SessionIdentity& id,std::uint64_t generation,std::uint64_t last,const ClockPair& now,const Timing& t)noexcept{return validTiming(t)&&validIdentity(id)&&p.identity==id&&generation>0&&generation<Max&&p.generation==generation&&p.closureGeneration==generation+1&&p.lastGrantSequence==last&&p.reason>Reason::None&&p.reason<=Reason::PeerClosed&&p.originalReference&&p.clockReliable&&window(p.closedAt,p.proofUntil,t.proofWindow)&&delta(p.closedAt,now,t.clockSkew)&&!reached(now,p.proofUntil);}
