void OwnerMachine::disconnect(ClockPair now)noexcept{if(!closed_){bool good=delta(lastClock_,now,timing_.clockSkew);shut(Reason::Disconnected,good?now:lastClock_,good);}}
void OwnerMachine::close(ClockPair now)noexcept{if(!closed_){bool good=delta(lastClock_,now,timing_.clockSkew);shut(Reason::Requested,good?now:lastClock_,good);}}
