ChildMachine::ChildMachine(SessionIdentity id,std::uint64_t gen,Timing timing,VerifiedPeer owner,std::uint32_t uid,ClockPair start)noexcept:identity_(id),timing_(timing),generation_(gen),peer_(owner),expectedUid_(uid),lastClock_(start),start_(start){if(!validIdentity(id))reason_=Reason::InvalidIdentity;else if(!validTiming(timing))reason_=Reason::InvalidTiming;else if(!gen||gen==Max||!clock(start))reason_=Reason::InvalidGeneration;else if(!peerMatches(owner,owner,uid,id.ownerPid))reason_=Reason::InvalidPeer;closed_=reason_!=Reason::None;}
void ChildMachine::shut(Reason reason)noexcept{if(closed_)return;closed_=true;active_=pending_=false;reason_=reason;}
bool ChildMachine::observe(ClockPair now,Authority auth)noexcept{if(closed_)return false;if(!delta(lastClock_,now,timing_.clockSkew)){shut(Reason::ClockDiscontinuity);return false;}lastClock_=now;if(auto bad=authority(auth);bad!=Reason::None){shut(bad);return false;}if(active_){if(reached(now,grant_.expires)){shut(Reason::GrantExpired);return false;}if(reached(now,grant_.drainAt)){shut(Reason::DrainDeadline);return false;}}else {ClockPair end;if(!plus(start_,timing_.startupBudget,end)){shut(Reason::CounterOverflow);return false;}if(reached(now,end)){shut(Reason::StartupExpired);return false;}}if(pending_&&reached(now,challenge_.replyBy)){shut(Reason::ChallengeExpired);return false;}if(hasHealth_){if(auto bad=pendingAge(lastHealth_,now,timing_);bad!=Reason::None){shut(bad);return false;}}return true;}
std::optional<Wire> ChildMachine::respond(std::span<const std::uint8_t> raw,VerifiedPeer peer,ClockPair now,Authority auth,HealthInput input)noexcept{if(!observe(now,auth))return {};auto reject=[&](Reason r)->std::optional<Wire>{shut(r);return {};};if(!peerMatches(peer,peer_,expectedUid_,identity_.ownerPid))return reject(Reason::InvalidPeer);auto m=decode(raw);if(!m||m->kind!=Kind::Challenge)return reject(Reason::Malformed);if(m->identity!=identity_)return reject(Reason::WrongIdentity);if(m->generation!=generation_)return reject(Reason::WrongGeneration);std::uint64_t expected,nextGrant;if(!next(challengeSequence_,expected)||!next(grantSequence_,nextGrant))return reject(Reason::CounterOverflow);if(pending_||m->sequence!=expected||m->challenge.nextGrant!=nextGrant)return reject(Reason::WrongSequence);if(m->challenge.nonce==challenge_.nonce)return reject(Reason::WrongNonce);if(!window(m->challenge.issued,m->challenge.replyBy,timing_.challengeLifetime)||!recent(m->challenge.issued,now,timing_.challengeLifetime,timing_.clockSkew)||reached(now,m->challenge.replyBy))return reject(Reason::FutureOrStale);if(!input.coherent)return reject(Reason::SnapshotUnavailable);if(auto bad=healthy(input.value,hasHealth_?&lastHealth_:nullptr,now,timing_);bad!=Reason::None)return reject(bad);if(!delta(m->challenge.issued,input.value.captured,timing_.clockSkew))return reject(Reason::FutureOrStale);Message reply;reply.kind=Kind::Health;reply.identity=identity_;reply.generation=generation_;reply.sequence=m->sequence;reply.responseNonce=m->challenge.nonce;reply.health=input.value;Wire encoded;if(!encode(reply,encoded))return reject(Reason::Malformed);challengeSequence_=m->sequence;challenge_=m->challenge;pending_=true;lastHealth_=input.value;hasHealth_=true;return encoded;}
bool ChildMachine::acceptGrant(std::span<const std::uint8_t> raw,VerifiedPeer peer,ClockPair now,Authority auth)noexcept{if(!observe(now,auth))return false;auto reject=[&](Reason r){shut(r);return false;};if(!peerMatches(peer,peer_,expectedUid_,identity_.ownerPid))return reject(Reason::InvalidPeer);auto m=decode(raw);if(!m||m->kind!=Kind::Grant)return reject(Reason::Malformed);if(m->identity!=identity_)return reject(Reason::WrongIdentity);if(m->generation!=generation_)return reject(Reason::WrongGeneration);std::uint64_t expected;if(!next(grantSequence_,expected))return reject(Reason::CounterOverflow);if(!pending_||m->sequence!=expected||m->grant.challengeSequence!=challengeSequence_||m->grant.mainSequence!=lastHealth_.mainSequence)return reject(Reason::WrongSequence);if(m->grant.nonce!=challenge_.nonce)return reject(Reason::WrongNonce);if(!window(m->grant.issued,m->grant.expires,timing_.grantLifetime)||!window(m->grant.issued,m->grant.drainAt,timing_.grantLifetime-timing_.drainLead)||!delta(challenge_.issued,m->grant.issued,timing_.clockSkew)||!recent(m->grant.issued,now,timing_.challengeLifetime,timing_.clockSkew)||reached(now,m->grant.drainAt))return reject(Reason::FutureOrStale);grant_=m->grant;grantSequence_=m->sequence;pending_=false;active_=true;return true;}
bool ChildMachine::acceptClosure(std::span<const std::uint8_t> raw,VerifiedPeer peer,ClockPair now)noexcept{if(closed_)return false;if(!delta(lastClock_,now,timing_.clockSkew)){shut(Reason::ClockDiscontinuity);return false;}auto m=decode(raw);bool valid=peerMatches(peer,peer_,expectedUid_,identity_.ownerPid)&&m&&m->kind==Kind::Closure&&m->identity==identity_&&m->generation==generation_&&m->sequence==grantSequence_&&m->closure.closureGeneration==generation_+1&&delta(m->closure.closedAt,now,timing_.clockSkew);shut(valid?Reason::PeerClosed:Reason::Malformed);return valid;}
bool ChildMachine::admitted(ClockPair now,Authority auth)noexcept{return observe(now,auth)&&active_;}
void ChildMachine::disconnect(ClockPair)noexcept{shut(Reason::Disconnected);}void ChildMachine::close(ClockPair)noexcept{shut(Reason::Requested);}
